<section class="admin-head"><div><p class="eyebrow">MakeOS · v0.7.4</p><h1>Quality & Evidence</h1><p>Defects, corrective action, lot inspection and private production evidence.</p></div></section>
<section class="admin-card"><h2>Choose workshop job</h2><form method="get" action="<?=e(url('/admin/quality'))?>"><select name="job"><option value="">Choose job</option><?php foreach($jobs as $j):?><option value="<?=e($j['guid'])?>" <?=$jobGuid===$j['guid']?'selected':''?>><?=e($j['number'].' · '.makeos_source_label($j))?></option><?php endforeach;?></select><button class="btn outline">Open quality record</button></form></section>
<?php if($jobGuid):?><section class="admin-card"><h2>Defects</h2><div class="table-wrap"><table><thead><tr><th>Ref</th><th>Stage</th><th>Severity</th><th>Description</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($defects as $d):?><tr><td><?=e($d['number'])?></td><td><?=e($d['stage'])?></td><td><?=e($d['severity'])?></td><td><?=e($d['description'])?></td><td><?=e($d['status'])?></td><td><?php if($d['status']!=='RESOLVED'):?><form method="post" action="<?=e(url('/admin/quality/defect/'.$d['guid'].'/action'))?>" class="stack"><?=csrf_field()?><textarea name="note" placeholder="Corrective action / resolution"></textarea><button class="btn outline" name="action" value="CORRECTIVE_ACTION">Corrective action</button><button class="btn primary" name="action" value="RESOLVE">Resolve</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-card"><h2>Production evidence</h2><div class="gallery-grid"><?php foreach($evidence as $e):?><figure><img src="<?=e(url('/admin/quality/evidence/'.$e['guid']))?>" alt="Production evidence"><figcaption><?=e($e['stage'].' · '.$e['caption'])?></figcaption></figure><?php endforeach;?></div></section><?php endif;?>
<section class="admin-card"><h2>Incoming lot quality</h2><div class="table-wrap"><table><thead><tr><th>Lot</th><th>Material</th><th>Available</th><th>Quality</th><th>Inspect</th></tr></thead><tbody><?php foreach($lots as $lot):?><tr><td><?=e($lot['lot_number'])?></td><td><?=e($lot['material_name'])?></td><td><?=e((string)$lot['qty_available'].' '.$lot['unit'])?></td><td><?=e($lot['quality_status']??'ACCEPTED')?></td><td><form method="post" action="<?=e(url('/admin/quality/lot/'.$lot['guid'].'/inspect'))?>" class="stack"><?=csrf_field()?><select name="decision"><option>ACCEPTED</option><option>QUARANTINED</option><option>REJECTED</option></select><input name="note" placeholder="Inspection note"><button class="btn outline">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
